INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230022', 'CV001', NULL, '2026-08-20', N'Trực tiếp tại văn phòng Khoa', N'Tư vấn kế hoạch cải thiện điểm học phần Lập trình Java và Cấu trúc dữ liệu', N'Làm thêm ca tối nhiều dẫn đến mệt mỏi, thiếu thời gian tự học', N'Giảm giờ làm thêm xuống dưới 15h/tuần, tham gia nhóm học tập kèm cặp', N'Cam kết đạt GPA >= 2.5 kỳ này và thi đạt 2 môn nợ');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230023', 'CV001', NULL, '2026-08-22', N'Trực tiếp tại văn phòng Khoa', N'Trao đổi về tình trạng nợ môn Toán cao cấp và Lập trình C', N'Chưa quen phương pháp tự học đại học, lúng túng làm bài tập lớn', N'Tham gia lớp trợ giảng phụ đạo của Khoa CNTT vào thứ 7', N'Cam kết đi học đầy đủ 100% các buổi học');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230026', 'CV001', NULL, '2026-08-24', N'Trực tiếp tại văn phòng Khoa', N'Tư vấn cảnh báo Mức 2 và lập biên bản cam kết tiến độ tốt nghiệp', N'Mất phương hướng học tập, gặp khó khăn môn Mạng máy tính', N'Chỉ đăng ký 14 tín chỉ trong kỳ tới, tập trung trả nợ 2 môn tiên quyết', N'Ký biên bản cam kết cải thiện GPA, phụ huynh đã nắm thông tin');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230028', 'CV001', NULL, '2026-08-26', N'Gọi điện thoại trao đổi phụ huynh', N'Thông báo tình hình vắng nhiều buổi và kết quả thi học kỳ', N'Gia đình có chuyện riêng, sinh viên phải đi làm phụ giúp kinh tế', N'Nhà trường hướng dẫn làm đơn xin giãn tiến độ và học bổng hỗ trợ', N'Sinh viên sắp xếp lại thời gian biểu và tham gia đầy đủ');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230122', 'CV002', NULL, '2026-08-22', N'Trực tiếp tại xưởng Ô tô', N'Tư vấn môn Thực hành động cơ và An toàn xưởng', N'Nghỉ 2 buổi thực hành do ốm, chưa hoàn thành bài tập xưởng', N'Đăng ký học bù vào sáng thứ 7 với kỹ thuật viên xưởng', N'Cam kết hoàn thành 100% bài thực hành trước kỳ thi');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230126', 'CV002', NULL, '2026-08-25', N'Trực tiếp tại văn phòng Khoa', N'Tư vấn cảnh báo Mức 2 chuyên ngành Kỹ thuật Ô tô', N'Nợ môn Cơ khí đại cương và Sức bền vật liệu', N'Được phân công bạn giỏi kèm cặp, CVHT kiểm tra bài tập 2 tuần/lần', N'Cam kết không nghỉ học và trả hết 2 môn trong học kỳ');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230222', 'CV003', NULL, '2026-08-23', N'Trực tiếp tại VP Khoa', N'Tư vấn môn Nguyên lý kế toán và Kinh tế vi mô', N'Hổng kiến thức nền tảng toán kinh tế', N'Tham gia câu lạc bộ học thuật QTKD để được hướng dẫn ôn tập', N'Cam kết làm đủ bài tập nhóm và nộp đúng hạn');
INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20230226', 'CV003', NULL, '2026-08-27', N'Trực tuyến qua MS Teams', N'Tư vấn xử lý học vụ cảnh báo Mức 2', N'Đi làm thêm kinh doanh online quá nhiều', N'Tạm hoãn việc kinh doanh, tập trung ôn thi học kỳ', N'Cam kết đạt điểm B các môn chuyên ngành');
